              Conversions.uriToBlob(img.src).then(function (blob) {
                  blobInfo = blobCache.create(uniqueId(), blob, base64);
                  blobCache.add(blobInfo);

                  resolve({
                      image: img,
                      blobInfo: blobInfo
                  });
              }, function (err) {
                  reject(err);
              });
